from os.path import join
from ta5g_dev_wro1.prepare_tech_log import MergeTestResults
import os.path


class CounterVerification(object):
    def __init__(self):
        pass

    def create_ascii_techlog_file(
        self, prepare_logs, bin_logs_name, output_csv_name, decoder, list_of_core_numbers, techlog_dir
    ):
        """
        Creates text techlog file
        """
        tech_logs = []
        for f in list_of_core_numbers:
            filename_old = "BTS1_{}_{}.bin.xz".format(f, bin_logs_name)
            filename_new = "BTS0_{}_{}.bin.xz".format(f, bin_logs_name)
            if os.path.isfile("{}/{}".format(techlog_dir, filename_old)):
                tech_logs.append(filename_old)
            else:
                tech_logs.append(filename_new)
        prepare_logs.prepare_tech_logs(tech_logs, decoder)
        tech_logs = [join(prepare_logs.tech_dir, log.replace('.xz', '.csv')) for log in tech_logs]
        merged_log = join(prepare_logs.tech_dir, output_csv_name)
        results = MergeTestResults(join(prepare_logs.tech_dir, output_csv_name))
        results.merge_tech_log(tech_logs)
        return merged_log

    def get_counter_sum(self, log_path, columns):
        """
        Method returns value of discarded packages by TUPu unit.
        """
        log_content = self._read_log(log_path)
        result = {}
        header = log_content.pop(0)
        header = header[:-1]
        splitted_header = header.split(",")
        absent_counters = ["\n"]
        for x in columns:
            try:
                column_num = self._get_column_number(splitted_header, x)
                result[x] = self._calculate_discarded_package(log_content, column_num)
            except Exception as e:
                absent_counters.append("".join(e))
        if len(absent_counters) != 1:
            raise Exception("\n".join(absent_counters))
        return result

    def _read_log(self, log_path):
        with open(log_path, "r") as f:
            return f.readlines()

    def _get_column_number(self, splitted_header, column_name):
        if column_name not in splitted_header:
            raise Exception("Cannot found column name: {}".format(column_name))
        return splitted_header.index(column_name)

    def _calculate_discarded_package(self, log, column_num):
        values = [int(line.split(",")[column_num]) for line in log]
        return sum(values)
